verify:
def parts(n, k, lo):
    if k == 1:
        return [[n]] if n >= lo else []
    return [[a] + r for a in range(lo, n // k + 1) for r in parts(n - a, k - 1, a)]
best = 0
for p in parts(36, 6, 1):
    if p[2] + p[3] == 10 and all(p.count(v) < p.count(4) for v in set(p) if v != 4):
        best = max(best, p[-1])
assert best == 14
assert Rational(spr_answers[0]) == best and len(spr_answers) == 1
